    // --- Courier drop points ---
    // One per district, at the nearest walkable tile to the
    // district's centre of mass -- so a leg is a journey and
    // the marker is somewhere the player was driving through
    // anyway, rather than a scrap of pavement behind a shop.
    struct MissionTarget {
        uint8_t tileX;
        uint8_t tileY;
    };
    static const uint8_t NUM_MISSION_TARGETS = 5;
    static const MissionTarget MISSION_TARGETS[NUM_MISSION_TARGETS] = {
        { 64, 38 },  // DOWNTOWN
        { 57, 98 },  // BEACH
        { 33, 84 },  // PARK
        { 70, 84 },  // MARINA
        { 99, 84 },  // SUBURBS
    };

    // --- Contract payphones ---
    // Where the main story is handed out. One row per
    // chapter, and that shape is the whole point: chapters 2
    // and 3 were each written by adding a row here rather than
    // a branch anywhere. Nothing is drawn into a layer for
    // these: a phone is a ring on the ground, like the courier
    // drop, and the player answers it on foot -- so every
    // entry is pedestrian-legal, off the carriageway, walkable
    // to from the spawn and at least one block clear of every
    // other ring INCLUDING THE OTHER PHONES, or two markers on
    // one corner could not be told apart.
    struct ContractPhone {
        uint8_t tileX;
        uint8_t tileY;
    };
    static const uint8_t NUM_CONTRACT_PHONES = 3;
    static const ContractPhone CONTRACT_PHONES[NUM_CONTRACT_PHONES] = {
        { 64, 21 },  // chapter 1, DOWNTOWN
        { 85, 82 },  // chapter 2, SUBURBS
        { 14, 76 },  // chapter 3, PARK
    };

    // --- Chapter 1, "Boost" ---
    // The parked car the player is sent to steal, and the drop
    // it has to be brought to. Indices, not coordinates: both
    // tables above are already emitted and a second copy of a
    // tile would be a second thing to keep in step.
    //
    // The car is the nearest one in a district OTHER than the
    // phone's -- a job you finish by turning round is not a
    // job -- and the drop is the courier point farthest from
    // that car, so the chapter ends in a drive across the
    // island rather than a nudge round the corner.
    static const uint8_t BOOST_VEHICLE_INDEX = 12;
    // (61,69) in MARINA, 51 tiles' walk from the phone
    static const uint8_t BOOST_DROP_INDEX = 4;
    // (99,84) in SUBURBS, 53 tiles' drive from the car

    // --- Chapter 2, "The Hit" ---
    // CONTRACT_PHONES[1] sends the player into the police
    // station to shoot one particular officer and walk back
    // out with the stars on. WHICH officer is this: a
    // subscript into police_station::OFFICERS, in the same
    // spirit as the two indices above -- the post is already
    // emitted, and a second copy of a coordinate is a second
    // thing to keep in step.
    //
    // It lives in the city's header rather than the
    // station's because it is a fact about the STORY and not
    // about the room: the station is a room full of police
    // whether or not anybody was ever sent to it, and every
    // other chapter constant is here.
    //
    // The mark is the officer FURTHEST FROM THE EXIT MAT,
    // counted in steps through the room's own furniture
    // rather than in a straight line. That is the argument
    // for it: a target by the door can be shot from the
    // doorway and the room never happens. The one at the far
    // end has to be walked to, past every other officer on
    // duty, which is the chapter.
    static const uint8_t HIT_OFFICER_INDEX = 0;
    // post (3,2) of 3, 18 steps in from the mat at (7,14)

    // And how far in that is, in STEPS, because the scene
    // has to pay for the walk and cannot work it out. The
    // clock chapter 2 starts covers the whole journey --
    // across the island to the door, then across the lobby
    // to this post -- and the second half is behind
    // furniture the city's header has never seen. The room
    // flood-fills its own floor to pick the mark in the
    // first place, so the number already exists here; the
    // scene recomputing it as a straight line would be a
    // second, WORSE answer to a question this file has
    // already answered exactly. The desk is solid, and the
    // post is chosen for being the furthest walk in the
    // room -- so a straight line is not merely approximate
    // here, it is approximate precisely where the mark is.
    static const uint8_t HIT_OFFICER_STEPS_IN = 18;
    // 18 walked against 16 in a straight line

    // --- Weapons lying in the street ---
    // The player starts unarmed. A pistol is an actor, not a
    // tile: nothing is written to a layer for these, they are
    // drawn on the ground and picked up by walking over them.
    // One per district, and the first is placed within sight of
    // the spawn so the mechanic is shown rather than explained.
    struct WeaponPickup {
        uint8_t tileX;
        uint8_t tileY;
        uint8_t weapon;    ///< weapons::WeaponId
    };
    static const uint8_t NUM_WEAPON_PICKUPS = 1;
    static const WeaponPickup WEAPON_PICKUPS[NUM_WEAPON_PICKUPS] = {
        { 59, 32, 0 },  // pistol, DOWNTOWN
    };

    // --- The buildings you can walk into ---
    // An entrance is drawn as open ground inside a building
    // stamp, so the player could already stand in it; these are
    // those cells. No door tile and no fourth layer were needed
    // -- the art was always walkable, nothing knew it meant
    // anything.
    //
    // The tile itself is still flagged SOLID, because the cell
    // is not empty: what makes it walkable is the per-pixel
    // Items test in CityCollision, which reads the silhouette.
    // A car or a pedestrian, tested whole-tile, cannot follow
    // the player in -- which is the behaviour anyway.
    static const uint16_t POLICE_DOOR_TILE_X = 67;
    static const uint16_t POLICE_DOOR_TILE_Y = 22;
    static const uint16_t SHOP_DOOR_TILE_X = 66;
    static const uint16_t SHOP_DOOR_TILE_Y = 35;

