    static const TileBehaviorLayer behavior_layers[] = {
        { TILE_BEHAVIOR_LAYER_BACKGROUND, 128, 128 },
        { TILE_BEHAVIOR_LAYER_ITEMS, 128, 128 },
        { TILE_BEHAVIOR_LAYER_DETAILS, 128, 128 },
    };
    static const uint8_t NUM_BEHAVIOR_LAYERS = 3;

    static const uint8_t BEHAVIOR_LAYER_BACKGROUND = 0;
    static const uint8_t BEHAVIOR_LAYER_ITEMS = 1;
    static const uint8_t BEHAVIOR_LAYER_DETAILS = 2;

    /// TileFlags at a cell, or TILE_NONE out of bounds.
    inline uint8_t getTileFlags(uint8_t layer_idx, int x, int y) {
        if (layer_idx >= NUM_BEHAVIOR_LAYERS) {
            return TILE_NONE;
        }
        return pixelroot32::physics::getTileFlags(
            behavior_layers[layer_idx], x, y);
    }

    // --- Minimap ink: street / ground / absent, per background tile ---
    // Indices into the ENGINE's built-in palette: the overlay is drawn
    // with primitives, and a primitive never sees this demo's custom
    // sprite palettes. CityConstants.h asserts them against gfx::Color.
    static const uint8_t MINIMAP_INK_STREET = 15;
    static const uint8_t MINIMAP_INK_GROUND = 8;
    static const uint8_t MINIMAP_SWATCH_BACKGROUND[77] = {
        8, 255, 255, 8, 8, 8, 8, 8, 255, 255, 255, 255, 255, 255, 255, 255,
        255, 255, 255, 255, 255, 255, 255, 8, 8, 8, 8, 8, 8, 8, 8, 8,
        8, 8, 8, 8, 8, 8, 8, 8, 8, 8, 8, 8, 8, 8, 8, 8,
        8, 8, 8, 8, 8, 15, 15, 15, 15, 15, 8, 15, 8, 8, 8, 8,
        8, 8, 8, 8, 8, 8, 8, 8, 8, 8, 8, 8, 8
    };

    /// District at a tile, from the coarse chunk grid.
    inline uint8_t zoneAt(int tileX, int tileY) {
        if (tileX < 0 || tileY < 0 ||
            tileX >= MAP_WIDTH || tileY >= MAP_HEIGHT) {
            return kZoneOcean;
        }
        return ZONE_GRID[(tileY / ZONE_CHUNK_TILES) * ZONE_GRID_WIDTH
                         + (tileX / ZONE_CHUNK_TILES)];
    }

